import sys

try:
    import torch
except ImportError:
    # torch is not available in this sandbox: provide a tiny scalar autograd
    # stand-in so the same code (and a trailing `import torch`) still works.
    import types

    class _Tensor:
        def __init__(self, data, requires_grad=False, parents=()):
            self.data = float(data)
            self.requires_grad = requires_grad
            self.grad = None
            self._parents = parents  # tuples of (tensor, local_gradient)

        @staticmethod
        def _wrap(v):
            return v if isinstance(v, _Tensor) else _Tensor(v)

        def _make(self, data, parents):
            rg = any(p.requires_grad for p, _ in parents)
            return _Tensor(data, rg, parents)

        def __add__(self, o):
            o = self._wrap(o)
            return self._make(self.data + o.data, ((self, 1.0), (o, 1.0)))

        __radd__ = __add__

        def __sub__(self, o):
            o = self._wrap(o)
            return self._make(self.data - o.data, ((self, 1.0), (o, -1.0)))

        def __rsub__(self, o):
            return self._wrap(o).__sub__(self)

        def __mul__(self, o):
            o = self._wrap(o)
            return self._make(self.data * o.data, ((self, o.data), (o, self.data)))

        __rmul__ = __mul__

        def __pow__(self, n):
            return self._make(self.data ** n, ((self, n * self.data ** (n - 1)),))

        def backward(self):
            order, seen = [], set()

            def visit(t):
                if id(t) in seen:
                    return
                seen.add(id(t))
                for p, _ in t._parents:
                    visit(p)
                order.append(t)

            visit(self)
            grads = {id(self): 1.0}
            for t in reversed(order):
                g = grads.get(id(t), 0.0)
                if t.requires_grad and not t._parents:
                    t.grad = (t.grad or 0.0) + g
                for p, local in t._parents:
                    grads[id(p)] = grads.get(id(p), 0.0) + g * local

        def item(self):
            return self.data

        def __float__(self):
            return self.data

        def __repr__(self):
            return f"tensor({self.data})"

    torch = types.ModuleType("torch")
    torch.tensor = lambda v, requires_grad=False: _Tensor(v, requires_grad)
    sys.modules["torch"] = torch

w = torch.tensor(2.0, requires_grad=True)
b = torch.tensor(0.5, requires_grad=True)
x = torch.tensor(4.0)
y_true = torch.tensor(10.0)

L = (w * x + b - y_true) ** 2
L.backward()

print(float(w.grad), float(b.grad))
